451			ToHolder: "李四", ToLocation: "B", HandedOverAt: at.Add(time.Hour),
452		}); !errors.Is(err, ErrConflict) {
453			t.Fatalf("重开后已销毁样品仍不得发起新交接, got %v", err)
454		}
455	}
456	
457	// TestDestroyLegacyDataWithoutDestruction 旧数据中没有销毁信息的样品一律
458	// 视为未销毁，即使剩余量为零也不能推断为销毁。
459	func TestDestroyLegacyDataWithoutDestruction(t *testing.T) {
460		dir := t.TempDir()
461		path := filepath.Join(dir, "legacy.json")
462		regAt := time.Date(2026, 10, 1, 9, 0, 0, 0, time.UTC)
463		legacy := ledger{
464			Version: 1,
465			Samples: map[string]*sampleRecord{
466				"OLD": {
467					ID:        "OLD",
468					Initial:   1000,
469					Remaining: 0, // 旧数据：分装用尽但没有销毁信息
470					Holder:    "h",
471					Location:  "l",
472					Children:  []string{},
473					History: []historyRecord{{
474						Kind: "register", Time: regAt, Holder: "h", Location: "l",
475					}},
476					// 没有 Destroyed 字段
477				},
478			},
479			Transfers: map[string]*transferRecord{},
480		}
481		raw, err := json.MarshalIndent(&legacy, "", "  ")
482		if err != nil {
483			t.Fatal(err)
484		}
485		if err := os.WriteFile(path, raw, 0o600); err != nil {
486			t.Fatal(err)
487		}
488	
489		s, err := Open(path)
490		if err != nil {
491			t.Fatal(err)
492		}
493		got, err := s.GetSample("OLD")
494		if err != nil {
495			t.Fatal(err)
496		}
497		if got.Remaining != "0.000" {
498			t.Fatalf("前置条件：剩余量应为 0.000, got %s", got.Remaining)
499		}
500		if got.Destruction != nil {
501			t.Fatalf("旧数据无销毁信息时不得推断为已销毁: %+v", got.Destruction)
502		}
503		// 视为未销毁且剩余量为零：销毁请求按冲突处理，而不是幂等返回。
504		if _, err := s.Destroy(DestroyInput{
505			SampleID: "OLD", Operator: "h", Location: "l",
506			At: regAt.Add(time.Hour), Reason: "r",
507		}); !errors.Is(err, ErrConflict) {
508			t.Fatalf("旧零剩余量样品销毁应 ErrConflict, got %v", err)
509		}
510	}
511	
512	// TestDestroyRejectedKeepsState 各类拒绝都不得改变数量、状态、历史。
513	func TestDestroyRejectedKeepsState(t *testing.T) {
514		s, _ := fixedStore(t)
515		mustRegister(t, s, "P", "1.500", "张三", "实验室A")
516		before, _ := s.GetSample("P")
517		at := time.Date(2026, 10, 2, 10, 0, 0, 0, time.UTC)
518	
519		try := func(in DestroyInput) {
520			t.Helper()
521			if _, err := s.Destroy(in); err == nil {
522				t.Fatalf("应拒绝: %+v", in)
523			}
524		}
525		try(DestroyInput{SampleID: "P", Operator: "李四", Location: "实验室A", At: at, Reason: "r"})
526		try(DestroyInput{SampleID: "P", Operator: "张三", Location: "X", At: at, Reason: "r"})
527		try(DestroyInput{SampleID: "P", Operator: "张三", Location: "实验室A", At: time.Time{}, Reason: "r"})
528		try(DestroyInput{SampleID: "P", Operator: "张三", Location: "实验室A", At: at, Reason: " "})
529		try(DestroyInput{SampleID: " ", Operator: "张三", Location: "实验室A", At: at, Reason: "r"})
530	
531		after, _ := s.GetSample("P")
532		if after.Remaining != before.Remaining || after.Holder != before.Holder ||
533			after.Location != before.Location || after.Destruction != nil ||
534			len(after.History) != len(before.History) {
535			t.Fatalf("被拒绝的销毁改动了状态: before=%+v after=%+v", before, after)
536		}
537	}
538

